namespace ghidra.feature.fid.plugin;



using docking;

/**
 * Dialog for the results of the ingest task.
 */
public class TextAreaDialog : DialogComponentProvider {
	JDialog outerDialog;

	public TextAreaDialog(string title, string text, bool modal) : base(title, modal)
    {
		addOKButton();
		addWorkPanel(createComponent(text));
	}

	private JComponent createComponent(string text) {
		JTextArea area = new JTextArea(text);
		area.setEditable(false);
		JScrollPane sp = new JScrollPane(area);
		return sp;
	}

	/* @Override */
	protected void okCallback() {
		close();
	}
}
